using namespace std;

long long mod_pow(long long base, long long exp, long long mod) {
    long long result = 1;
    while (exp > 0) {
        if (exp % 2 == 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp /= 2;
    }
    return result;
}

int main() {
    long long p, k;
    cin >> p >> k;
    const long long pcon = 1000000007;
    vector<long long> obr(1000003, 0);
    obr[1] = 1;
    for (long long i = 2; i < 1000003; ++i) {
        long long a = pcon / i;
        long long b = pcon % i;
        long long c = (a * (pcon - obr[b])) % pcon;
        obr[i] = c;
    }
    long long ans = 0;
    if (k == 0) {
        ans = 1;
        for (long long i = 0; i < p - 1; ++i) {
            ans = (ans * p) % pcon;
        }
    } else {
        long long io = 1, lk = 0, jj = 0;
        for (long long i = 1; i < p; ++i) {
            io = (io * k) % p;
            if ((io % p) == 1 && lk == 0) {
                jj = i;
                lk = 1;
            }
        }
        ans = 1;
        long long t = (p - 1) / jj;
        if (k == 1) {
            ans = 1;
            for (long long i = 0; i < p; ++i) {
                ans = (ans * p) % pcon;
            }
        } else {
            long long pr = 1;
            for (long long i = 1; i <= t; ++i) {
                pr = (pr * obr[i]) % pcon;
                pr = (pr * (t - i + 1)) % pcon;
                pr = (pr * t) % pcon;
                pr = (pr * jj) % pcon;
                ans = (ans + pr) % pcon;
            }
        }
    }
    cout << ans;
}
